    enonce: "a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">6a + 4b = 134</span> و <span dir=\"ltr\" class=\"expr\">ab = 165</span> فكّك إلى جداء عوامل العبارة <span dir=\"ltr\" class=\"expr\">F = 24a + 16b + 36</span> ثمّ جد قيمتها العددية",
    correction: [{"quoi":"نبحث عن عامل مشترك","math":"الأعداد 24 و 16 و 36 كلّها مضاعفات لـ 4"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">24a + 16b + 36 = 4(6a + 4b + 9)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">6a + 4b = 134</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">134 + 9 = 143</span>"},{"quoi":"نضرب","math":"<span dir=\"ltr\" class=\"expr\">4 × 143 = 572</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = 572</span>"}],
